import { spawn } from 'node:child_process';
import path from 'node:path';
export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
const state = globalThis as typeof globalThis & { hevcConnections?: number };
export async function GET(request: Request) {
  const source = new URL(request.url).searchParams.get('source') || (process.env.CAMERA_RTSP_URL ? 'camera' : 'demo');
  if (!['demo','camera'].includes(source)) return new Response('Unknown source', {status:400});
  if (request.headers.get('sec-fetch-site') === 'cross-site') return new Response('Forbidden', {status:403});
  const camera = process.env.CAMERA_RTSP_URL;
  if (source === 'camera' && !camera) return new Response('Set CAMERA_RTSP_URL on the server first.', {status:503});
  if ((state.hevcConnections || 0) >= 4) return new Response('Preview connection limit reached.', {status:429});
  state.hevcConnections = (state.hevcConnections || 0) + 1;
  const input = source === 'demo'
    ? ['-re','-stream_loop','-1','-i',path.join(process.cwd(),'public/media/demo.mp4')]
    : ['-rtsp_transport','tcp','-timeout','15000000','-i',camera!];
  const processHandle = spawn(/* turbopackIgnore: true */ process.env.FFMPEG_PATH || 'ffmpeg', [
    '-hide_banner','-loglevel','error',...input,'-map','0:v:0','-an','-c:v','copy',
    '-mpegts_flags','+resend_headers','-muxdelay','0','-muxpreload','0','-f','mpegts','pipe:1'
  ], {stdio:['ignore','pipe','pipe']});
  let stderr = '';
  // Accumulate before redacting, since credentials can span stderr chunks.
  processHandle.stderr.on('data', (chunk: Buffer) => { stderr = (stderr + chunk.toString()).slice(-16384); });
  const diagnostics = () => {
    let message = stderr;
    if (camera) {
      message = message.split(camera).join('[camera URL]');
      try {
        const parsed = new URL(camera);
        for (const secret of [parsed.password, decodeURIComponent(parsed.password)]) {
          if (secret) message = message.split(secret).join('[redacted]');
        }
      } catch {}
    }
    return message.replace(/rtsps?:\/\/[^\s]+/gi, '[camera URL]').slice(-4000).trim();
  };
  let closed = false;
  let killTimer: ReturnType<typeof setTimeout>;
  const cleanup = () => {
    if (closed) return;
    closed = true;
    state.hevcConnections = Math.max(0,(state.hevcConnections || 1)-1);
    clearTimeout(idleTimer);
    request.signal.removeEventListener('abort', onAbort);
    processHandle.kill('SIGTERM');
    killTimer = setTimeout(() => processHandle.kill('SIGKILL'),2000);
    killTimer.unref();
  };
  let streamController: ReadableStreamDefaultController<Uint8Array>;
  const finish = (error?: Error) => {
    if (closed) return;
    cleanup();
    if (error) streamController.error(error); else streamController.close();
  };
  const onAbort = () => finish();
  const idleTimer = setTimeout(() => finish(new Error('Stream timed out')),20000);
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      streamController = controller;
      processHandle.stdout.on('data',(chunk: Buffer) => {
        if (closed) return;
        idleTimer.refresh();
        controller.enqueue(new Uint8Array(chunk));
        if ((controller.desiredSize || 0) <= 0) processHandle.stdout.pause();
      });
      processHandle.on('error',() => finish(new Error('Unable to start FFmpeg. Check server installation.')));
      processHandle.on('close',(code) => {
        clearTimeout(killTimer);
        if (!closed && code !== 0) console.error('[hevc-gateway] FFmpeg exit', code, diagnostics() || 'No diagnostic output');
        finish(code && code !== 0 ? new Error('Stream unavailable. Check server camera configuration.') : undefined);
      });
      request.signal.addEventListener('abort',onAbort,{once:true});
      if (request.signal.aborted) onAbort();
    },
    pull() { processHandle.stdout.resume(); },
    cancel() { cleanup(); }
  }, {highWaterMark: 1024 * 1024, size: chunk => chunk.byteLength});
  return new Response(stream,{headers:{'Content-Type':'video/mp2t','Cache-Control':'no-store','X-Accel-Buffering':'no'}});
}
